26	function sanitizeWorksTheatreState(
27	  state: Record<string, unknown> | null,
28	): Record<string, unknown> | null {
29	  if (!state) return null;
30	  const sheetsByIdValue = state.sheetsById;
31	  if (
32	    sheetsByIdValue == null ||
33	    typeof sheetsByIdValue !== "object" ||
34	    Array.isArray(sheetsByIdValue)
35	  ) {
36	    return state;
37	  }
38	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
39	  const nextSheetsById: Record<string, unknown> = {};
40	  WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
41	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
42	    nextSheetsById[sheetId] = sheetsById[sheetId];
43	  });
44	  return {
45	    ...state,
46	    sheetsById: nextSheetsById,
47	  };
48	}
